MB = 1024 ** 2
GB = 1024 ** 3

def parse_size(text):
    match = re.fullmatch(r'(\d+)(B|KB|MB|GB)', text)
    if not match:
        raise ValueError
    number, unit = match.groups()
    if unit == 'B':
        return int(number)
    if unit == 'KB':
        return int(number) * KB
    if unit == 'MB':
        return int(number) * MB
    if unit == 'GB':
        return int(number) * GB

