import re

def compare_versions(a, b):
    version_regex = re.compile(r'^([0-9]+)(\.[0-9]+)*$')

    match_a = version_regex.match(a)
    match_b = version_regex.match(b)

    if not match_a or not match_b:
        raise ValueError

    a_parts = match_a.groups()
    b_parts = match_b.groups()

    a_major = int(a_parts[0])
    b_major = int(b_parts[0])

    if a_major < b_major:
        return -1
    elif a_major > b_major:
        return 1
    else:
        for a, b in zip(a_parts[1:], b_parts[1:]):
            a_minor, a_patch = a.split('.')
            b_minor, b_patch = b.split('.')
            a_minor = int(a_minor)
            b_minor = int(b_minor)
            if a_minor < b_minor:
                return -1
            elif a_minor > b_minor:
                return 1
            else:
                a_patch = int(a_patch)
                b_patch = int(b_patch)
                if a_patch < b_patch:
                    return -1
                elif a_patch > b_patch:
                    return 1
                else:
                    return 0

