def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError

    if s == '':
        return ''

    encoded = []
    count = 1
    for i in range(1, len(s) + 1):
        if i == len(s) or s[i] != s[i - 1]:
            encoded.append(s[i - 1])
            encoded.append(str(count))
            count = 1
        else:
            count += 1

    return ''.join(encoded)

