class TaskQueue:
    def __init__(self):
        self._queue = []
        self._count = 0

    def add(self, name, priority):
        if (name, priority) in [(item[2], item[1]) for item in self._queue]:
            raise ValueError(f"Name {name} is already in the queue with the same priority.")
        heapq.heappush(self._queue, (priority, self._count, name))
        self._count += 1

    def pop(self):
        if not self._queue:
            raise IndexError("pop from an empty TaskQueue")
        return heapq.heappop(self._queue)[-1]

    def __len__(self):
        return len(self._queue)

