class TaskQueue:
    def __init__(self):
        self.queue = []

    def add(self, name, priority):
        if name in [item[2] for item in self.queue]:
            raise ValueError(f"{name} is already in the queue.")
        heapq.heappush(self.queue, (priority, len(self.queue), name))

    def pop(self):
        if not self.queue:
            raise IndexError("pop from an empty TaskQueue")
        return heapq.heappop(self.queue)[2]

    def __len__(self):
        return len(self.queue)
